/*
 * 2026-11-11：飞书剪存轮询（方案 A）第 2~6 步的端到端守卫。
 *
 * 链路：wiki +node-list → docs +fetch 读正文 → 判定 Generated by Feishu Clip
 *   → 写 数据源/raw → 总结 → 写 知识库列表/<库> → 同步回飞书对应知识库。
 *
 * 用**真实临时目录 + 注入的假 lark/总结/同步**跑整条编排：能验落盘路径、frontmatter、
 * 游标幂等、跳过非剪存、总结不可用时不写假笔记、以及同步只针对目标库目录。
 *
 * 跑法：node dsh-plugins/vssaros-kb/scripts/check-kb-feishu-clip.mjs
 */
import { mkdtempSync, mkdirSync, readFileSync, existsSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import assert from 'node:assert/strict';

const HERE = new URL('.', import.meta.url);
const clip = await import(new URL('../lib/core/feishuClip.js', HERE).href);
const { runClipPipeline } = await import(new URL('../lib/core/feishuClipPipeline.js', HERE).href);
const INDEX = readFileSync(new URL('../lib/index.js', HERE), 'utf8');
const CLIP_SRC = readFileSync(new URL('../lib/core/feishuClip.js', HERE), 'utf8');

let pass = 0, fail = 0;
const check = (name, fn) => {
	try { fn(); pass++; console.log('PASS  ' + name); }
	catch (e) { fail++; console.log('FAIL  ' + name + ' — ' + String(e?.message ?? e)); }
};

// ── 纯函数 ──────────────────────────────────────────────────────────────────
check('① nodeListArgs：列空间节点 + 分页 + json，user 身份带 --as user', () => {
	const a = clip.nodeListArgs('my_library', 'user');
	assert.deepEqual(a.slice(0, 6), ['wiki', '+node-list', '--space-id', 'my_library', '--page-all', '--format']);
	assert.equal(a.includes('json'), true);
	assert.equal(a.at(-2), '--as');
	assert.equal(a.at(-1), 'user');
	assert.equal(clip.nodeListArgs('sp_1', 'bot').includes('--as'), false);
	assert.equal(clip.nodeListArgs('', 'user')[3], 'my_library');
});
check('② clipDocArgs：用 obj_token 取 markdown 正文', () => {
	const a = clip.clipDocArgs('doc_123');
	assert.deepEqual(a.slice(0, 4), ['docs', '+fetch', '--doc', 'doc_123']);
	assert.ok(a.includes('markdown'));
});
check('③ parseNodeList：宽松解析 + token 去重 + 混日志行不炸', () => {
	const raw = 'log line\n' + JSON.stringify({ ok: true, data: { items: [
		{ node_token: 'nod_1', obj_token: 'doc_1', title: '剪存A', obj_type: 'docx', obj_create_time: '1700' },
		{ node_token: 'nod_1', obj_token: 'doc_1', title: '重复' },
		{ node_token: 'nod_2', obj_token: 'doc_2', title: '剪存B', obj_type: 'docx' },
	] } });
	const list = clip.parseNodeList(raw, '');
	assert.equal(list.length, 2, '没按 token 去重');
	assert.equal(list[0].title, '剪存A');
	assert.equal(list[0].createTime, '1700');
	assert.deepEqual(clip.parseNodeList('not json at all'), []);
});
check('④ isClipDoc：大小写不敏感，普通文档不误判', () => {
	assert.equal(clip.isClipDoc('正文\n\ngenerated by feishu clip\n'), true);
	assert.equal(clip.isClipDoc('普通会议纪要'), false);
	assert.equal(clip.isClipDoc('x', '自定义标记'), false);
});
check('⑤ 配置归一化 + 目录段净化（拒 .. / 剥知识库列表前缀）', () => {
	const c = clip.clipConfigOf({ targetKb: '知识库列表/剪存笔记', limit: 999, identity: 'bot' });
	assert.equal(c.targetKb, '剪存笔记');
	assert.equal(c.limit, 50);
	assert.equal(c.identity, 'bot');
	assert.equal(clip.clipConfigOf({ targetKb: '../etc' }).targetKb, '');
	assert.equal(clip.clipConfigOf(null).enabled, false);
});
check('⑥ slug / raw 素材无 frontmatter / 笔记补 frontmatter', () => {
	assert.equal(clip.slugOf('OpenAI 新功能: 发布', 'doc_1'), 'OpenAI-新功能-发布');
	assert.equal(clip.slugOf('///', 'doc_1').startsWith('clip-'), true);
	const raw = clip.rawMarkdownOf({ title: 'T', markdown: 'B', at: '2026-11-11' });
	assert.ok(raw.startsWith('# T\n'));
	assert.ok(!raw.startsWith('---'), 'raw 素材不能写 YAML frontmatter ✗');
	const note = clip.noteMarkdownOf({ title: 'T', body: '## 概述\n\n正文', sourceRel: '数据源/raw/T.md', at: '2026-11-11T00:00:00Z' });
	assert.ok(note.startsWith('---\n'));
	assert.ok(note.includes('sources: ["数据源/raw/T.md"]'));
	assert.equal(clip.noteMarkdownOf({ title: 'T', body: '---\ntitle: X\n---\n', sourceRel: 'r', at: '' }).startsWith('---\n'), true);
	assert.equal(clip.noteMarkdownOf({ body: '' }), '');
});
check('⑦ 游标：坏 JSON 不抛、序列化可往返', () => {
	assert.deepEqual(clip.parseCursor('{bad'), { version: 1, seen: {}, lastRun: '' });
	const c = clip.parseCursor(clip.serializeCursor({ seen: { doc_1: { at: 'x' } }, lastRun: 'y' }));
	assert.equal(c.seen.doc_1.at, 'x');
	assert.equal(c.lastRun, 'y');
});

// ── 端到端编排（真实临时目录 + 注入依赖） ───────────────────────────────────
const tmp = mkdtempSync(join(tmpdir(), 'kb-clip-'));
const vault = join(tmp, 'vault');
mkdirSync(vault, { recursive: true });
const CFG = {
	enabled: true, spaceId: 'my_library', identity: 'user',
	targetKb: '剪存笔记', targetSpaceId: '7651000000000000001', limit: 5,
};
const NODES = [
	{ node_token: 'nod_1', obj_token: 'doc_1', title: 'OpenAI 新功能', obj_type: 'docx', obj_create_time: '1700000000000' },
	{ node_token: 'nod_2', obj_token: 'doc_2', title: '普通会议纪要', obj_type: 'docx', obj_create_time: '1700000001000' },
];
function makeDeps({ withSummary = true } = {}) {
	const larkCalls = [];
	const syncCalls = [];
	const lark = async (args) => {
		larkCalls.push(args);
		if (args[1] === '+node-list') {
			return { code: 0, stdout: JSON.stringify({ ok: true, data: { items: NODES } }), stderr: '' };
		}
		if (args[1] === '+fetch') {
			const isClip = args[3] === 'doc_1';
			return {
				code: 0,
				stdout: JSON.stringify({ ok: true, data: { document: {
					title: isClip ? 'OpenAI 新功能' : '普通会议纪要',
					content: isClip ? '# OpenAI 新功能\n\n正文段落。\n\nGenerated by Feishu Clip\n' : '# 会议纪要\n\n普通内容\n',
				} } }),
				stderr: '',
			};
		}
		return { code: 1, stdout: '', stderr: 'unexpected args' };
	};
	const summarize = withSummary
		? async ({ title }) => `## 概述\n\n${title} 的摘要\n\n## 关键要点\n\n- 要点一\n\n## 关联\n\n- 无\n`
		: null;
	const sync = async (p) => { syncCalls.push(p); return { ok: true, code: 0 }; };
	return {
		larkCalls, syncCalls,
		deps: {
			lark,
			...(withSummary ? { summarize } : {}),
			sync,
			now: () => '2026-11-11T10:00:00.000Z',
		},
	};
}

try {
	const first = makeDeps();
	const r1 = await runClipPipeline({ cfg: CFG, vaultRoot: vault, apply: true, deps: first.deps });
	check('⑧ ★ 全链路：1 篇剪存导入 + 1 篇普通文档跳过', () => {
		assert.equal(r1.ok, true, r1.error);
		assert.equal(r1.phase, 'done');
		assert.equal(r1.listed, 2);
		assert.equal(r1.imported.length, 1);
		assert.equal(r1.skipped.length, 1);
		assert.equal(r1.skipped[0].why, '非剪存文档');
		assert.equal(r1.pendingSummary.length, 0);
	});
	check('⑨ ★ raw 落在 数据源/raw（素材层），笔记落在 知识库列表/<目标库>', () => {
		const hit = r1.imported[0];
		assert.ok(hit.rawRel.startsWith('数据源/raw/'));
		assert.ok(hit.noteRel.startsWith('知识库列表/剪存笔记/'));
		const raw = readFileSync(join(vault, hit.rawRel), 'utf8');
		assert.ok(raw.includes('Generated by Feishu Clip'));
		assert.ok(!raw.startsWith('---'));
		const note = readFileSync(join(vault, hit.noteRel), 'utf8');
		assert.ok(note.startsWith('---\n'), '笔记缺 frontmatter');
		assert.ok(note.includes('## 概述') && note.includes('sources:'));
		assert.equal(existsSync(join(vault, '知识库列表/剪存笔记/普通会议纪要.md')), false);
	});
	check('⑩ ★ 第 6 步：只同步目标库目录，且带 spaceId 映射', () => {
		assert.equal(first.syncCalls.length, 1);
		const p = first.syncCalls[0];
		assert.equal(p.srcDir, '知识库列表/剪存笔记');
		assert.equal(p.extraMappings[0].dir, '知识库列表/剪存笔记');
		assert.equal(p.extraMappings[0].spaceId, CFG.targetSpaceId);
		assert.equal(r1.sync?.ok, true);
	});
	const second = makeDeps();
	const r2 = await runClipPipeline({ cfg: CFG, vaultRoot: vault, apply: true, deps: second.deps });
	check('⑪ ★ 游标幂等：第二轮不再重复导入', () => {
		assert.equal(r2.imported.length, 0, '重复导入了 ✗');
		assert.equal(r2.sync, null, '没有新笔记却触发了同步 ✗');
		assert.equal(r2.cursor.seen, 2);
		const cursor = JSON.parse(readFileSync(join(vault, '.kb/clip-cursor.json'), 'utf8'));
		assert.ok(cursor.seen.doc_1 && cursor.seen.doc_2);
	});
	const dry = makeDeps();
	const dryRoot = join(tmp, 'dry-vault');
	mkdirSync(dryRoot, { recursive: true });
	const rd = await runClipPipeline({ cfg: CFG, vaultRoot: dryRoot, apply: false, deps: dry.deps });
	check('⑫ dry-run 只读计划：不写盘、不推进游标、不同步', () => {
		assert.equal(rd.phase, 'dry-run');
		assert.equal(rd.candidates.length, 2);
		assert.equal(rd.imported.length, 0);
		assert.equal(existsSync(join(dryRoot, '.kb/clip-cursor.json')), false);
		assert.equal(dry.syncCalls.length, 0);
		assert.equal(dry.larkCalls.length, 1, 'dry-run 不该逐篇读正文');
	});
	const noSum = makeDeps({ withSummary: false });
	const noSumRoot = join(tmp, 'nosum-vault');
	mkdirSync(noSumRoot, { recursive: true });
	const rn = await runClipPipeline({ cfg: CFG, vaultRoot: noSumRoot, apply: true, deps: noSum.deps });
	check('⑬ ★ 总结服务不可用：不写假笔记、不推进游标（下次自动重试）', () => {
		assert.equal(rn.imported.length, 0);
		assert.equal(rn.pendingSummary.length, 1);
		assert.ok(rn.pendingSummary[0].why.includes('总结服务'));
		assert.equal(noSum.syncCalls.length, 0);
		const cursor = JSON.parse(readFileSync(join(noSumRoot, '.kb/clip-cursor.json'), 'utf8'));
		assert.equal(cursor.seen.doc_1, undefined, '失败的篇不该被标记已处理 ✗');
		assert.ok(existsSync(join(noSumRoot, '数据源/raw/OpenAI-新功能.md')), 'raw 素材仍应保留');
		assert.equal(existsSync(join(noSumRoot, '知识库列表/剪存笔记')), false);
	});
	const noTarget = makeDeps();
	const noTargetRoot = join(tmp, 'notarget-vault');
	mkdirSync(noTargetRoot, { recursive: true });
	const rt = await runClipPipeline({ cfg: { ...CFG, targetKb: '' }, vaultRoot: noTargetRoot, apply: true, deps: noTarget.deps });
	check('⑭ 未配置目标知识库：挂起而不乱写笔记', () => {
		assert.equal(rt.imported.length, 0);
		assert.ok(rt.pendingSummary.some(p => p.why.includes('targetKb')));
	});
	const badList = { lark: async () => ({ code: 1, stdout: '', stderr: '{"error":{"code":19001,"msg":"invalid access token"}}' }) };
	const rl = await runClipPipeline({ cfg: CFG, vaultRoot: vault, apply: true, deps: badList });
	check('⑮ 列节点失败：给可读错误（带动作上下文与真实原因）', () => {
		assert.equal(rl.ok, false);
		assert.equal(rl.phase, 'list');
		assert.ok(rl.error.includes('列举飞书知识库节点'));
		assert.ok(rl.error.includes('invalid access token'));
	});
	const noScope = {
		lark: async () => ({ code: 1, stdout: '', stderr: JSON.stringify({
			error: { code: 99991672, missing_scopes: ['wiki:wiki'], identity: 'bot' },
		}) }),
	};
	const rs = await runClipPipeline({ cfg: CFG, vaultRoot: vault, apply: true, deps: noScope });
	check('⑮b 缺 wiki scope：复用 99991672 解析器给权限指引，不当成普通失败', () => {
		assert.equal(rs.ok, false);
		assert.ok(rs.error.includes('缺少飞书知识库权限') && rs.error.includes('wiki:wiki'));
	});
} catch (e) {
	fail++;
	console.log('FAIL  端到端夹具异常 — ' + String(e?.message ?? e));
} finally {
	rmSync(tmp, { recursive: true, force: true });
}

// ── 静态接线 ────────────────────────────────────────────────────────────────
check('⑯ Host 侧：手动端点 / 状态端点 / 定时器 / 配置分节都在', () => {
	for (const needle of ['/api/clip-run', '/api/clip-status', 'startClipPollScheduler',
		'clipPoll: { ...CLIP_DEFAULTS }', 'readClipSettings', 'clipDeps']) {
		assert.ok(INDEX.includes(needle), 'index.js 缺 ' + needle);
	}
	assert.ok(/performFeishuSync\(config, \{ dry = false, srcDir = '', extraMappings = \[\] \}/.test(INDEX));
	assert.ok(/if \(srcDir\) \{ syncOpts\.src = \[srcDir\]; \}/.test(INDEX), '同步没限定目标目录');
});
check('⑰ 默认安全：POST 须显式 apply，定时器默认关闭', () => {
	assert.ok(/const apply = body\?\.apply === true/.test(INDEX));
	assert.ok(/enabled: false,/.test(CLIP_SRC) && /scheduleMinutes: 10,/.test(CLIP_SRC),
		'剪存轮询必须默认关闭（要点开关才跑）');
	assert.ok(/approval: \{ allow: \[\] \}/.test(INDEX), '总结回合不该带工具权限');
});

// ── fake Host：确认 HTTP 端点真的注册进了 /x/kb 路由 ────────────────────────
const FND = await import(new URL('../../vssaros-foundation/lib/index.js', HERE).href);
const KB = await import(new URL('../lib/index.js', HERE).href);
let handler;
const noop = () => () => {};
const foundation = FND.createFoundationService();
const ctx = new Proxy({}, {
	get(_t, key) {
		if (key === 'inject') {
			return (deps, cb) => {
				if (Array.isArray(deps) && deps.includes('webServer')) {
					cb({ effect: fn => { fn(); return noop(); }, connection: { requestRejection: () => undefined },
						webServer: { register: spec => { handler = spec.handler; return noop(); } } });
				} else if (Array.isArray(deps) && deps.includes('vssarosFoundation')) {
					cb({ vssarosFoundation: foundation });
				}
				return noop();
			};
		}
		if (key === 'effect') { return fn => { try { const d = fn(); return typeof d === 'function' ? d : noop(); } catch { return noop(); } }; }
		if (key === 'get') { return n => (n === 'vssarosFoundation' ? foundation : null); }
		if (key === 'tools') { return { register: noop }; }
		if (key === 'on') { return noop; }
		return undefined;
	},
});
const hostTmp = mkdtempSync(join(tmpdir(), 'kb-clip-host-'));
try {
	KB.apply(ctx, { dataRoot: hostTmp, hostHalf: true });
	const out = [];
	await handler({ method: 'GET', url: '/x/kb/api/clip-status' },
		{ writeHead() {}, end(b) { out.push(String(b ?? '')); } });
	const st = JSON.parse(out.join('') || '{}');
	check('⑱ ★ GET /x/kb/api/clip-status 真注册：默认关闭且配置可读', () => {
		assert.equal(st.ok, true);
		assert.equal(st.config.enabled, false, '剪存轮询默认必须关闭');
		assert.equal(st.config.spaceId, 'my_library');
		assert.equal(st.config.targetKb, '', '目标库默认空 ⇒ 不乱写笔记');
		assert.equal(st.state.running, false);
	});
} catch (e) {
	fail++;
	console.log('FAIL  fake Host 端点异常 — ' + String(e?.message ?? e));
} finally {
	rmSync(hostTmp, { recursive: true, force: true });
}

console.log(`\n${pass}/${pass + fail} passed`);
if (fail) { process.exit(1); }
